            throw new PropelException('Cannot insert a value for auto-increment primary key ('.SolicitudPrestamoPeer::SOLICITUDPRESTAMO_ID.')');
        }

        // remove pkey col since this table uses auto-increment and passing a null value for it is not valid
        $criteria->remove(SolicitudPrestamoPeer::SOLICITUDPRESTAMO_ID);


        // Set the correct dbName
        $criteria->setDbName(SolicitudPrestamoPeer::DATABASE_NAME);

        try {
